/// <reference types="cypress" />

import {
  diffLines,
  getChangedLines,
  toLineRanges,
  updateSignal,
} from "../../src/components/Workspace/codeDiff";

const baseCode = [
  "// Code generated by senseBox Blockly on Mon Jan 01 2024",
  "#include <Wire.h>",
  "",
  "void setup() {",
  "}",
  "",
  "void loop() {",
  "}",
].join("\n");

const withBlock = [
  "// Code generated by senseBox Blockly on Tue Jan 02 2024",
  "#include <Wire.h>",
  "#include <SPI.h>",
  "",
  "void setup() {",
  "  Wire.begin();",
  "}",
  "",
  "void loop() {",
  "  delay(1000);",
  "}",
].join("\n");

describe("Code signaling", () => {
  it("[CodeSignaling] detects added lines and ignores the timestamp", () => {
    expect(getChangedLines(baseCode, withBlock)).to.deep.eq([3, 6, 10]);
  });

  it("[CodeSignaling] detects a changed line", () => {
    const changed = withBlock.replace("delay(1000)", "delay(500)");
    expect(getChangedLines(withBlock, changed)).to.deep.eq([10]);
  });

  it("[CodeSignaling] highlights the appended block, not an identical line above", () => {
    const head = (date) =>
      `// Code generated by senseBox Blockly on ${date}\n\nvoid setup() {\n}\n\nvoid loop() {\n`;
    const before = head("Mon") + "  digitalWrite(1, HIGH);\n  delay(1000);\n}";
    const after =
      head("Tue") +
      "  digitalWrite(1, HIGH);\n  delay(1000);\n" +
      "  digitalWrite(1, LOW);\n  delay(1000);\n}";
    expect(getChangedLines(before, after)).to.deep.eq([9, 10]);
  });

  it("[CodeSignaling] maps unchanged lines so the highlight can follow them", () => {
    const removed = withBlock.replace("  Wire.begin();\n", "");
    const { changed, lineMap } = diffLines(withBlock, removed);
    expect(changed).to.deep.eq([]);
    expect(lineMap.get(10)).to.eq(9); // delay(1000) moved up one line
    expect(lineMap.has(6)).to.eq(false); // removed line has no new position
  });

  it("[CodeSignaling] highlights the dropped block, not code generated mid-drag", () => {
    const loop = (body) =>
      `// Code generated by senseBox Blockly on x\n\nvoid loop() {\n${body}\n}`;
    const pd = [
      "  display.setCursor(0,0);",
      "  display.setTextSize(1);",
      "  display.setTextColor(WHITE,BLACK);",
      '  display.println("Hallo");',
    ].join("\n");
    const before = loop("  display.display();");
    // While dragging, the floating block's code is appended to loop()
    const duringDrag = loop(`  display.display();\n\n${pd}`);
    const afterDrop = loop(`${pd}\n  display.display();`);

    let signal = { baseCode: before, baseHighlight: [] };
    signal = updateSignal(signal, duringDrag, { dragging: true }).state;
    const { highlight, reveal } = updateSignal(signal, afterDrop);

    expect(highlight).to.deep.eq([4, 5, 6, 7]);
    expect(reveal).to.eq(true);
  });

  it("[CodeSignaling] keeps the highlight when nothing new is added", () => {
    const first = updateSignal(
      { baseCode: baseCode, baseHighlight: [] },
      withBlock,
    );
    const same = withBlock.replace("Tue Jan 02", "Wed Jan 03");
    const second = updateSignal(first.state, same);
    expect(second.highlight).to.deep.eq([3, 6, 10]);
    expect(second.reveal).to.eq(false);
  });

  it("[CodeSignaling] does not highlight a loaded workspace", () => {
    const loaded = updateSignal(
      { baseCode: baseCode, baseHighlight: [3] },
      withBlock,
      { reset: true },
    );
    expect(loaded.highlight).to.deep.eq([]);
    expect(loaded.state.baseCode).to.eq(withBlock);
  });

  it("[CodeSignaling] reports nothing when lines are only removed", () => {
    expect(getChangedLines(withBlock, baseCode)).to.deep.eq([]);
  });

  it("[CodeSignaling] groups lines into ranges", () => {
    expect(toLineRanges([3, 4, 5, 9])).to.deep.eq([
      { start: 3, end: 5 },
      { start: 9, end: 9 },
    ]);
  });

  it("[CodeSignaling] does not highlight code on initial load", () => {
    cy.visit("/");
    cy.get('img[alt="Sensebox ESP"]', { timeout: 8000 }).click();
    cy.get("#codeviewer-headline").should("be.visible");
    cy.get(".monaco-editor .view-lines", { timeout: 10000 }).should(
      "contain.text",
      "setup",
    );
    cy.get(".code-signal-line").should("not.exist");
  });
});
